function validate([sentences]) {
  if (!Array.isArray(sentences) || sentences.length < 1 || sentences.length > 100) return 'sentences needs 1 to 100 strings.';
  for (const s of sentences) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 100) return 'Each sentence has 1 to 100 characters.';
    if (!/^[a-z]+( [a-z]+)*$/.test(s)) return 'Each sentence is lowercase words separated by single spaces, with no leading or trailing space.';
  }
  return null;
}

