function mostWordsFound(sentences) {
  let most = 0;
  for (const sentence of sentences) {
    let words = 1;
    for (const ch of sentence) {
      if (ch === ' ') {
        words++;
      }
    }
    most = Math.max(most, words);
  }
  return most;
}

