function generate(rand, size) {
  const count = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const limit = size === 'large' ? 100 : 14;
  const sentences = [];
  for (let i = 0; i < count; i++) {
    const maxLen = 1 + Math.floor(rand() * limit);
    const longest = rand() < 0.5 ? 1 : 1 + Math.floor(rand() * 6);
    const words = [];
    let length = -1;
    for (;;) {
      const len = 1 + Math.floor(rand() * longest);
      if (words.length > 0 && length + 1 + len > maxLen) break;
      let word = '';
      for (let k = 0; k < len; k++) word += String.fromCharCode(97 + Math.floor(rand() * 26));
      words.push(word);
      length += 1 + len;
      if (length >= maxLen) break;
    }
    sentences.push(words.join(' ').slice(0, 100));
  }
  return [sentences];
}
